package queue

import (
	"fmt"
	"sync"
	"time"
)

// Message represents a single item in the queue.
type Message struct {
	ID   string
	Body []byte
}

// MessageState tracks the current state of a message.
type MessageState struct {
	Message      *Message
	State        string    // "available", "in-flight", "acknowledged"
	LeaseID      string    // set when claimed under a lease
	LeaseExpires time.Time // when this lease expires
}

// Queue manages messages with lease-based claiming.
type Queue struct {
	mu       sync.RWMutex
	messages map[string]*MessageState
	nextID   int64
}

// New creates a new queue.
func New() *Queue {
	return &Queue{
		messages: make(map[string]*MessageState),
	}
}

// Enqueue adds a message to the queue.
func (q *Queue) Enqueue(body []byte) string {
	q.mu.Lock()
	defer q.mu.Unlock()

	q.nextID++
	msgID := fmt.Sprintf("msg-%d", q.nextID)

	q.messages[msgID] = &MessageState{
		Message: &Message{ID: msgID, Body: body},
		State:   "available",
	}
	return msgID
}

// ClaimBatch claims up to 50 available messages under a single lease.
func (q *Queue) ClaimBatch(leaseID string, leaseDuration time.Duration) []*Message {
	q.mu.Lock()
	defer q.mu.Unlock()

	const batchSize = 50
	claimed := make([]*Message, 0, batchSize)
	leaseExpires := time.Now().Add(leaseDuration)

	for msgID, state := range q.messages {
		if len(claimed) >= batchSize {
			break
		}

		if state.State == "available" {
			state.State = "in-flight"
			state.LeaseID = leaseID
			state.LeaseExpires = leaseExpires
			claimed = append(claimed, state.Message)
		}
	}

	return claimed
}

// Acknowledge marks messages as processed, removing them from the queue.
func (q *Queue) Acknowledge(leaseID string, messageIDs []string) error {
	q.mu.Lock()
	defer q.mu.Unlock()

	for _, msgID := range messageIDs {
		state, exists := q.messages[msgID]
		if !exists {
			return fmt.Errorf("message not found: %s", msgID)
		}

		if state.State != "in-flight" || state.LeaseID != leaseID {
			return fmt.Errorf("message %s not in-flight under lease %s", msgID, leaseID)
		}

		state.State = "acknowledged"
		delete(q.messages, msgID)
	}

	return nil
}

// ReleaseExpiredLeases finds messages whose leases have expired and returns them to available.
// This is typically called periodically by a background goroutine.
func (q *Queue) ReleaseExpiredLeases() int {
	q.mu.Lock()
	defer q.mu.Unlock()

	now := time.Now()
	released := 0

	for _, state := range q.messages {
		if state.State == "in-flight" && now.After(state.LeaseExpires) {
			state.State = "available"
			state.LeaseID = ""
			state.LeaseExpires = time.Time{}
			released++
		}
	}

	return released
}

// Size returns the current number of messages in the queue.
func (q *Queue) Size() int {
	q.mu.RLock()
	defer q.mu.RUnlock()
	return len(q.messages)
}

// Stats returns statistics about the queue.
func (q *Queue) Stats() map[string]int {
	q.mu.RLock()
	defer q.mu.RUnlock()

	stats := make(map[string]int)
	for _, state := range q.messages {
		stats[state.State]++
	}
	return stats
}

