package queue

import (
	"fmt"
	"testing"
	"time"
)

func TestEnqueueAndClaimBatch(t *testing.T) {
	q := New()

	// Enqueue 60 messages
	for i := 0; i < 60; i++ {
		q.Enqueue([]byte(fmt.Sprintf("message-%d", i)))
	}

	// Claim a batch of up to 50
	batch1 := q.ClaimBatch("lease-1", 1*time.Second)
	if len(batch1) != 50 {
		t.Errorf("expected batch of 50, got %d", len(batch1))
	}

	// Claim remaining (should be 10)
	batch2 := q.ClaimBatch("lease-2", 1*time.Second)
	if len(batch2) != 10 {
		t.Errorf("expected batch of 10, got %d", len(batch2))
	}

	// No more messages available
	batch3 := q.ClaimBatch("lease-3", 1*time.Second)
	if len(batch3) != 0 {
		t.Errorf("expected empty batch, got %d", len(batch3))
	}
}

func TestAcknowledge(t *testing.T) {
	q := New()

	msgID1 := q.Enqueue([]byte("msg1"))
	msgID2 := q.Enqueue([]byte("msg2"))

	batch := q.ClaimBatch("lease-1", 1*time.Second)
	if len(batch) != 2 {
		t.Fatalf("expected 2 messages, got %d", len(batch))
	}

	// Acknowledge first message
	err := q.Acknowledge("lease-1", []string{msgID1})
	if err != nil {
		t.Errorf("unexpected error: %v", err)
	}

	if q.Size() != 1 {
		t.Errorf("expected 1 message remaining, got %d", q.Size())
	}

	// Acknowledge second message
	err = q.Acknowledge("lease-1", []string{msgID2})
	if err != nil {
		t.Errorf("unexpected error: %v", err)
	}

	if q.Size() != 0 {
		t.Errorf("expected 0 messages, got %d", q.Size())
	}
}

func TestLeaseExpiration(t *testing.T) {
	q := New()

	msgID := q.Enqueue([]byte("msg"))

	// Claim with a very short lease
	batch := q.ClaimBatch("lease-1", 10*time.Millisecond)
	if len(batch) != 1 {
		t.Fatalf("expected 1 message, got %d", len(batch))
	}

	// Message should still be in queue but in-flight
	if q.Size() != 1 {
		t.Errorf("expected 1 message in queue, got %d", q.Size())
	}

	stats := q.Stats()
	if stats["in-flight"] != 1 {
		t.Errorf("expected 1 in-flight message, got %d", stats["in-flight"])
	}

	// Wait for lease to expire
	time.Sleep(50 * time.Millisecond)

	// Release expired leases
	released := q.ReleaseExpiredLeases()
	if released != 1 {
		t.Errorf("expected 1 released message, got %d", released)
	}

	// Message should be available again
	stats = q.Stats()
	if stats["available"] != 1 {
		t.Errorf("expected 1 available message, got %d", stats["available"])
	}

	// Should be able to claim it again
	batch2 := q.ClaimBatch("lease-2", 1*time.Second)
	if len(batch2) != 1 {
		t.Errorf("expected to reclaim message, got %d", len(batch2))
	}
}

func TestAcknowledgeErrors(t *testing.T) {
	q := New()

	msgID := q.Enqueue([]byte("msg"))
	batch := q.ClaimBatch("lease-1", 1*time.Second)
	if len(batch) != 1 {
		t.Fatalf("expected 1 message, got %d", len(batch))
	}

	// Try to acknowledge with wrong lease ID
	err := q.Acknowledge("lease-2", []string{msgID})
	if err == nil {
		t.Error("expected error when acknowledging with wrong lease")
	}

	// Try to acknowledge non-existent message
	err = q.Acknowledge("lease-1", []string{"nonexistent"})
	if err == nil {
		t.Error("expected error for non-existent message")
	}
}

func TestStats(t *testing.T) {
	q := New()

	for i := 0; i < 5; i++ {
		q.Enqueue([]byte(fmt.Sprintf("msg-%d", i)))
	}

	batch := q.ClaimBatch("lease-1", 1*time.Second)
	if len(batch) != 5 {
		t.Fatalf("expected 5 messages, got %d", len(batch))
	}

	stats := q.Stats()
	if stats["in-flight"] != 5 {
		t.Errorf("expected 5 in-flight, got %d", stats["in-flight"])
	}

	q.Acknowledge("lease-1", []string{batch[0].ID})

	stats = q.Stats()
	if stats["in-flight"] != 4 {
		t.Errorf("expected 4 in-flight after ack, got %d", stats["in-flight"])
	}
}

