	// Try to acknowledge non-existent message
	err = q.Acknowledge("lease-1", []string{"nonexistent"})
	if err == nil {
		t.Error("expected error for non-existent message")
	}
}

func TestStats(t *testing.T) {
	q := New()

	for i := 0; i < 5; i++ {
		q.Enqueue([]byte(fmt.Sprintf("msg-%d", i)))
	}

	batch := q.ClaimBatch("lease-1", 1*time.Second)
	if len(batch) != 5 {
		t.Fatalf("expected 5 messages, got %d", len(batch))
	}

	stats := q.Stats()
	if stats["in-flight"] != 5 {
		t.Errorf("expected 5 in-flight, got %d", stats["in-flight"])
	}

	q.Acknowledge("lease-1", []string{batch[0].ID})

	stats = q.Stats()
	if stats["in-flight"] != 4 {
		t.Errorf("expected 4 in-flight after ack, got %d", stats["in-flight"])
	}
}

