func (w *Worker) Process() int {
	leaseID := fmt.Sprintf("lease-%s-%d", w.id, time.Now().UnixNano())

	batch := w.q.ClaimBatch(leaseID, w.lease)
	if len(batch) == 0 {
		return 0
	}

	log.Printf("[%s] Claimed %d messages under lease %s", w.id, len(batch), leaseID)

	// Simulate processing: some messages succeed, some fail
	ackIDs := make([]string, 0, len(batch))
	for _, msg := range batch {
		// Simulate work with random success rate
		if rand.Float64() < 0.9 { // 90% success rate
			ackIDs = append(ackIDs, msg.ID)
			log.Printf("[%s] Processed %s", w.id, msg.ID)
		} else {
			log.Printf("[%s] Failed to process %s (will retry on lease expiry)", w.id, msg.ID)
		}
	}

	// Acknowledge successfully processed messages
	if len(ackIDs) > 0 {
		err := w.q.Acknowledge(leaseID, ackIDs)
		if err != nil {
			log.Printf("[%s] Error acknowledging messages: %v", w.id, err)
			return 0
		}
		log.Printf("[%s] Acknowledged %d messages", w.id, len(ackIDs))
	}

	return len(ackIDs)
}

