	q := queue.New()

	// Enqueue some messages
	for i := 0; i < 100; i++ {
		q.Enqueue([]byte(fmt.Sprintf("message-%d", i)))
	}

	log.Printf("Enqueued 100 messages")

	// Create multiple workers
	workers := make([]*Worker, 3)
	for i := 0; i < 3; i++ {
		workers[i] = NewWorker(fmt.Sprintf("worker-%d", i), q, 2*time.Second)
	}

	// Start background goroutine to release expired leases
	go func() {
		ticker := time.NewTicker(100 * time.Millisecond)
		defer ticker.Stop()
		for range ticker.C {
			released := q.ReleaseExpiredLeases()
			if released > 0 {
				log.Printf("Released %d expired messages", released)
			}
		}
	}()

	// Simulate workers processing in rounds
	for round := 1; round <= 5; round++ {
		log.Printf("=== Round %d ===", round)

		totalProcessed := 0
		for _, w := range workers {
			processed := w.Process()
			totalProcessed += processed
		}

		log.Printf("Round %d: Processed %d messages", round, totalProcessed)

		stats := q.Stats()
		log.Printf("Queue stats: available=%d, in-flight=%d, acknowledged=%d",
			stats["available"], stats["in-flight"], stats["acknowledged"])

		time.Sleep(500 * time.Millisecond)
	}

	log.Printf("Final queue size: %d", q.Size())
}

